const finishButton=document.createElement('button');finishButton.id='finishCount';finishButton.className='outline';finishButton.type='button';finishButton.textContent='סיום ספירה';$('workspace').append(finishButton);
finishButton.onclick=async()=>{const s=session();if(s.completedAt){try{await globalThis.milaiAccess.finish(s);showFinishSummary()}catch(e){toast(e.message)}return}if(!globalThis.milaiAccess?.canWrite(s)){toast('הרישיון אינו מאפשר סיום של הספירה הזאת');return}if(!confirm(`לסיים את הספירה „${s.name}” ובה ${Object.keys(s.items).length} מוצרים? לאחר האישור היא תישאר לצפייה ולייצוא בלבד. סריקות ותיקונים נוספים לא יתאפשרו במחזור הזה.`))return;if(await mutate(()=>{s.completedAt=Date.now();s.reopenClosedToken=globalThis.milaiAccess.currentReopenToken()})){try{await globalThis.milaiAccess.finish(s);toast('הספירה הסתיימה ונשמרה במכשיר')}catch(e){toast('הספירה נשמרה כסגורה. אישור הסיום טרם סונכרן: '+e.message)}render();showFinishSummary()}};
const backupFolder=document.createElement('button');backupFolder.type='button';backupFolder.className='text-button';backupFolder.textContent='בחירת תיקייה לגיבוי נוסף';$('backupAdvanced').append(backupFolder);
const recoveryButton=document.createElement('button');recoveryButton.type='button';recoveryButton.className='text-button';recoveryButton.textContent='עותק התאוששות מהמכשיר';$('backupAdvanced').append(recoveryButton);
const backupStatus=document.createElement('p');backupStatus.className='form-note';backupStatus.setAttribute('role','status');backupStatus.textContent='הנתונים נשמרים מקומית. גיבוי חיצוני עדיין לא נשמר בפעולה הזאת.';$('backupAdvanced').append(backupStatus);
async function externalBackup(choose=false){try{if(choose){if(!window.showDirectoryPicker)throw Error('הדפדפן אינו מאפשר בחירת תיקייה. השתמש בהורדת גיבוי JSON ושמור אותו במקום נוסף');externalDirectory=await window.showDirectoryPicker({mode:'readwrite',id:'mb-inventory-backups'});await inventoryStorage.setHandle(externalDirectory)}if(!externalDirectory)throw Error('לא נבחרה תיקיית גיבוי');const result=await saveExternalCopies(externalDirectory,state);lastExternalBackup=result.savedAt;backupStatus.textContent=`נשמר ונבדק קובץ גיבוי אחד בתיקייה שנבחרה · ${new Date(lastExternalBackup).toLocaleString('he-IL')}`;if(choose)toast('קובץ גיבוי אחד נשמר ונבדק')}catch(e){backupStatus.textContent='לא נשמר גיבוי חיצוני: '+e.message;if(choose)toast(backupStatus.textContent)}}
backupFolder.onclick=()=>externalBackup(true);
const recoveryDialog=document.createElement('dialog');recoveryDialog.innerHTML='<div class="dialog-top"><h2>עותק התאוששות במכשיר</h2><button class="close" type="button" aria-label="סגירה">×</button></div><p>עותק אוטומטי אחרון שנשמר בדפדפן. אפשר להוריד אותו ואז לשחזר דרך „שחזור גיבוי”.</p><div class="recovery-list"></div>';document.body.append(recoveryDialog);recoveryDialog.querySelector('.close').onclick=()=>recoveryDialog.close();
recoveryButton.onclick=async()=>{try{const rows=await inventoryStorage.recoveryCopies(),list=recoveryDialog.querySelector('.recovery-list');list.replaceChildren();for(const row of rows){const b=document.createElement('button');b.className='outline';b.type='button';b.textContent=(row.kind==='migration'?'העותק המקורי לפני העברת אחסון':'עותק התאוששות')+' · '+new Date(row.createdAt).toLocaleString('he-IL');b.onclick=()=>download(new Blob([row.raw],{type:'application/json'}),'MB-Inventory-recovery-'+row.createdAt+'.json');list.append(b)}if(!rows.length)list.textContent='אין עדיין עותקי התאוששות';recoveryDialog.showModal()}catch(e){toast('לא ניתן לקרוא עותקי התאוששות: '+e.message)}};
if(navigator.storage?.persisted)navigator.storage.persisted().then(persisted=>{if(!persisted)backupStatus.textContent+=' מומלץ להוריד עותק נוסף מחוץ למכשיר.'}).catch(()=>{});
const persistentButton=document.createElement('button');persistentButton.type='button';persistentButton.className='text-button';persistentButton.textContent='הגנה על השמירה במכשיר';$('backupAdvanced').append(persistentButton);persistentButton.onclick=async()=>{const granted=await navigator.storage?.persist?.();toast(granted?'הדפדפן אישר אחסון מתמשך. עדיין חשוב גיבוי חיצוני':'לא אושרה שמירה מתמשכת. מומלץ לשמור גיבוי חיצוני')};
const storageMode=document.createElement('section');storageMode.className='form-note';storageMode.innerHTML='<b>שמירה במכשיר</b><p role="status">בודק את האחסון המקומי…</p><button type="button" class="text-button">בדיקת מקום פנוי</button>';const storageDetails=document.createElement('details');storageDetails.className='storage-help';const storageSummary=document.createElement('summary');storageSummary.textContent='מידע נוסף על השמירה';storageDetails.append(storageSummary,storageMode);$('backupAdvanced').append(storageDetails);const storageModeText=storageMode.querySelector('p');const bytesText=n=>n<1024*1024?`${(n/1024).toFixed(0)} KB`:`${(n/1024/1024).toFixed(1)} MB`;async function updateStorageMode(){try{if(!navigator.storage?.estimate){storageModeText.textContent='הדפדפן אינו מספק נתוני שימוש ומכסה. הספירות נשמרות במכשיר הזה.';return}const {usage,quota}=await navigator.storage.estimate();if(!Number.isFinite(usage)||!Number.isFinite(quota)||quota<=0){storageModeText.textContent='לא התקבלו נתוני שימוש או מכסה מהדפדפן.';return}const percent=Math.min(100,Math.round(usage/quota*100));let persisted='';if(navigator.storage.persisted){try{persisted=(await navigator.storage.persisted())?' · אחסון מתמשך אושר':' · אחסון מתמשך לא אושר'}catch{}}storageModeText.textContent=`שימוש משוער בדפדפן: ${bytesText(usage)} מתוך ${bytesText(quota)} (${percent}%)${persisted}. הספירות נשמרות במכשיר הזה.`}catch{storageModeText.textContent='לא ניתן לקרוא נתוני שימוש ומכסה כרגע. הספירות ממשיכות להישמר במכשיר הזה.'}}storageMode.querySelector('button').onclick=updateStorageMode;updateStorageMode();

let syncingAccess=false;
async function syncSessionAccess(){
 if(syncingAccess||storageError)return;syncingAccess=true;
 try{
  const reopened=await synchronizeReopen({state,access:globalThis.milaiAccess,mutate});
  if(reopened){
   if($('finishSummary').open)$('finishSummary').close();
   toast(`המנהל פתח מחדש את „${reopened.name}”. אפשר להמשיך אותה דרך הספירות השמורות`);
  }
  const current=sessionForActivation();
  if(current&&!current.completedAt&&(current.licenseClaimRequired||Object.keys(current.items||{}).length>0))await globalThis.milaiAccess?.acquire(current);
  if(globalThis.milaiAccess?.business)await mutate(()=>{state.business={...state.business,...globalThis.milaiAccess.business}},false,true);
 }catch(e){toast('לא ניתן לבדוק פתיחה מחדש כרגע: '+e.message)}finally{syncingAccess=false}
}
document.addEventListener('milai-license-change',()=>syncSessionAccess());
await syncSessionAccess();

function connection(){$('connection').textContent=navigator.onLine?'מוכן לעבודה':'עבודה ללא אינטרנט'}window.addEventListener('online',connection);window.addEventListener('offline',connection);connection();render();
try{if(!storageError&&inventoryStorage)await inventoryStorage.save(state)}catch{storageError=true;toast('השמירה במכשיר אינה זמינה. הנתונים הקודמים לא נמחקו. הורד גיבוי לפני המשך הספירה.')}
if('serviceWorker'in navigator){let checkingUpdate=false;const showUpdate=()=>{if(document.getElementById('reloadUpdate'))return;const b=document.createElement('button');b.id='reloadUpdate';b.type='button';b.className='primary';b.textContent='קיימת גרסה חדשה — שמור וטען עדכון';b.onclick=async()=>{await mutationQueue;if(document.querySelector('dialog[open]')&&!confirm('העדכון יטען מחדש את המסך. סגור תחילה טופס שלא נשמר. להמשיך?'))return;location.reload()};document.querySelector('main').prepend(b)};navigator.serviceWorker.addEventListener('controllerchange',showUpdate);navigator.serviceWorker.register('sw.js',{updateViaCache:'none'}).then(reg=>{const check=async()=>{if(checkingUpdate||!navigator.onLine)return;checkingUpdate=true;try{await reg.update()}catch{}finally{checkingUpdate=false}};document.addEventListener('visibilitychange',()=>{if(!document.hidden)check()});return navigator.serviceWorker.ready}).then(()=>$('saved').textContent='נשמר במכשיר · זמין גם ללא אינטרנט').catch(()=>{});}

if(session().completedAt&&globalThis.milaiAccess?.countId===session().countId)globalThis.milaiAccess.finish(session()).catch(()=>{});

document.querySelector('.mobile-nav')?.addEventListener('click',event=>{const button=event.target.closest('[data-nav]');if(!button)return;const action=button.dataset.nav;if(action==='count')document.querySelector('#workspace').scrollIntoView({behavior:'smooth',block:'start'});else if(action==='inventory')document.querySelector('#inventory').scrollIntoView({behavior:'smooth',block:'start'});else if(action==='scan')$('scan').click();else if(action==='export')$('export').click();else if(action==='account')document.querySelector('.activation-bar button')?.click()});
